## Group By Function

Here's a clean, reusable JavaScript function that groups an array of objects by a specified key:

```javascript
/**
 * Groups an array of objects by a given key.
 * @param {Object[]} array - The array of objects to group.
 * @param {string|Function} key - The key to group by, or a function that returns the group key.
 * @returns {Object} An object where keys are group names and values are arrays of objects.
 */
function groupBy(array, key) {
  if (!Array.isArray(array)) {
    throw new TypeError("First argument must be an array");
  }

  return array.reduce((result, item) => {
    const groupKey = typeof key === "function" ? key(item) : item[key];

    if (groupKey === undefined) {
      console.warn(`Key "${key}" not found in item:`, item);
    }

    const groupName = String(groupKey ?? "undefined");

    if (!result[groupName]) {
      result[groupName] = [];
    }

    result[groupName].push(item);

    return result;
  }, {});
}
```

