// Edge cases
snakeToCamel("alreadycamel");         // "alreadycamel" (no change)
snakeToCamel("single");              // "single"
snakeToCamel("UPPER_CASE");          // "upperCase"
snakeToCamel("mixed_CASE_string");   // "mixedCaseString"
snakeToCamel("");                    // ""

