  return retry(fn, maxRetries, {
    onRetry: async (error, attempt) => {
      const backoffDelay = baseDelay * 2 ** (attempt - 1); // 100, 200, 400...
      console.log(`Retrying in ${backoffDelay}ms...`);
      await sleep(backoffDelay);
    },
  });
}
```

