### 2. Modern Asynchronous Version (Recommended)

In modern JavaScript, operations that might fail (like network requests) are almost always asynchronous and return a `Promise`. A simple `try...catch` in a loop won't work correctly with Promises. The best way to handle this is with `async/await`.

This version is highly recommended as it handles both synchronous functions and asynchronous functions (that return Promises) gracefully.

```javascript
/**
 * Retries an async or sync callback function up to N times if it throws or rejects.
 *
 * @template T
 * @param {() => Promise<T> | T} callback The function to execute.
 * @param {number} maxAttempts The total number of attempts to make.
 * @returns {Promise<T>} A promise that resolves with the callback's result or rejects with the last error.
 */
async function retry(callback, maxAttempts) {
  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      // The 'await' keyword works for both promises and synchronous values.
      // If callback() returns a value, it's wrapped in a resolved promise.
      // If it throws, it's caught. If it returns a rejecting promise, it's also caught.
      return await callback();
    } catch (error) {
      lastError = error;
      console.log(`Attempt ${attempt} of ${maxAttempts} failed. Retrying...`);

      // If this was the last attempt, we don't need to wait before throwing.
      if (attempt === maxAttempts) {
        break; // Exit the loop to throw the error
      }
    }
  }

  // If we're here, all attempts failed.
  console.error(`All ${maxAttempts} attempts failed.`);
  // Re-throw the last captured error.
  throw lastError;
}

// --- Example Usage ---

// An async function that simulates a failing API call
let apiCallCount = 0;
function fetchUnreliableData() {
  return new Promise((resolve, reject) => {
    apiCallCount++;
    console.log(`Fetching data... (attempt #${apiCallCount})`);
    setTimeout(() => {
      if (apiCallCount < 3) {
        reject(new Error("Network Error: Could not fetch data."));
      } else {
        resolve({ id: 123, name: "John Doe" });
      }
    }, 500);
  });
}

// We use .then/.catch or an async IIFE to handle the promise returned by retry()
(async () => {
  try {
    const data = await retry(fetchUnreliableData, 4);
    console.log("Successfully fetched data:", data);
  } catch (error) {
    console.error("Failed to fetch data after multiple retries:", error.message);
  }
})();
```

### 3. Advanced Version with Configurable Delay (Exponential Backoff)

For real-world scenarios, you don't want to retry immediately. It's better to wait between attempts, often increasing the delay each time. This is called "exponential backoff" and is a very common pattern.

```javascript
/**
 * A utility function to create a delay.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>}
 */
