/**
 * Retries an async or sync callback with configurable attempts and exponential backoff delay.
 *
 * @template T
 * @param {() => Promise<T> | T} callback The function to execute.
 * @param {object} options Configuration options.
 * @param {number} [options.maxAttempts=3] The total number of attempts.
 * @param {number} [options.delay=200] The initial delay in milliseconds.
 * @param {function(Error, number): void} [options.onRetry] An optional callback for logging on each retry.
 * @returns {Promise<T>} A promise that resolves with the callback's result or rejects with the last error.
 */
async function retryWithBackoff(callback, options = {}) {
  const {
    maxAttempts = 3,
    delay = 200,
    onRetry
  } = options;

  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await callback();
    } catch (error) {
      lastError = error;

      if (attempt === maxAttempts) {
        // No more retries left, break the loop to throw the final error.
        break;
      }

      if (onRetry) {
        onRetry(error, attempt);
      }

      // Calculate exponential backoff delay
      const backoffDelay = delay * Math.pow(2, attempt - 1);
      // console.log(`Attempt ${attempt} failed. Retrying in ${backoffDelay}ms...`);
      await wait(backoffDelay);
    }
  }

  // Using the 'cause' property is a modern way to chain errors.
  throw new Error(`Function failed after ${maxAttempts} attempts.`, { cause: lastError });
}


