  return new Promise((resolve, reject) => {
    // Simulate network delay
    setTimeout(() => {
      if (Math.random() > 0.3) {
        reject(new Error(`API Error: Failed to fetch data on attempt ${attemptCounter}.`));
      } else {
        resolve({ data: `Success on attempt ${attemptCounter}!` });
      }
    }, 500);
  });
