/**
 * Retries an async callback with exponential backoff.
 *
 * @param {function} callback The async function to execute.
 * @param {object} options Configuration options.
 * @param {number} [options.retries=3] The maximum number of attempts.
 * @param {number} [options.delay=1000] The initial delay in ms.
 * @param {number} [options.factor=2] The factor by which to multiply the delay each time.
 * @returns {Promise<*>} A promise that resolves with the result of the callback.
 * @throws {Error} Rejects with an error if the callback fails after all retries.
 */
async function retryWithBackoff(callback, options = {}) {
  const { retries = 3, delay = 1000, factor = 2 } = options;
  let currentDelay = delay;
  let lastError;

  for (let i = 1; i <= retries; i++) {
    try {
      return await callback();
    } catch (error) {
      lastError = error;
      console.error(`Attempt ${i} failed: ${error.message}`);

      if (i < retries) {
        console.log(`Waiting ${currentDelay}ms before next retry...`);
        await wait(currentDelay);
        currentDelay *= factor; // Increase delay for the next attempt
      }
    }
  }

  throw new Error(`Failed after ${retries} attempts. Last error: ${lastError.message}`);
}

