### 2. Production-Ready `retry` with Exponential Backoff

In a real-world scenario, you shouldn't retry immediately. You should wait for a short period, and that period should increase after each failure. This is called **exponential backoff** and it prevents you from overwhelming a service that might be temporarily down.

```javascript
/**
 * A utility function to create a delay.
 * @param {number} ms The number of milliseconds to wait.
 * @returns {Promise<void>}
 */
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Retries an async function with exponential backoff.
 *
 * @param {Function} asyncCallback The async function to retry.
 * @param {number} maxRetries The maximum number of retries.
 * @param {number} [initialDelay=1000] The initial delay in ms.
 */
async function retryWithBackoff(asyncCallback, maxRetries, initialDelay = 1000) {
  let lastError;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      return await asyncCallback();
    } catch (error) {
      lastError = error;
      console.log(`Attempt ${attempt} failed. Error: ${error.message}`);

      if (attempt > maxRetries) {
        console.log("All retries failed.");
        break;
      }

      // Calculate delay: 1s, 2s, 4s, etc.
      const delayTime = initialDelay * Math.pow(2, attempt - 1);
      console.log(`Waiting ${delayTime}ms before next retry...`);
      await delay(delayTime);
    }
  }

  throw lastError;
}

