### 1. Modern `async/await` Version (Recommended)

This version is the most versatile. It handles functions that return a `Promise` (like `fetch`) and also works correctly with regular synchronous functions. It includes configurable options for the number of retries, the delay between retries, and an optional `onRetry` callback for logging.

```javascript
/**
 * A helper function to pause execution for a given time.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>} A promise that resolves after the specified delay.
 */
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Retries a function that returns a Promise, up to N times if it rejects.
 *
 * @param {Function} fn The asynchronous function to execute.
 * @param {object} [options={}] Configuration options.
 * @param {number} [options.retries=3] The maximum number of retries.
 * @param {number} [options.delay=1000] The initial delay between retries in ms.
 * @param {boolean} [options.backoff=true] Whether to use exponential backoff for delay.
 * @param {Function} [options.onRetry] A callback function to be invoked on each retry attempt.
 *                                     It receives the error and the current attempt number.
 * @returns {Promise<any>} A promise that resolves with the result of the function `fn`
 *                         or rejects with the last error after all retries fail.
 */
async function retry(fn, options = {}) {
  // Set default options
  const {
    retries = 3,
    delay = 1000,
    backoff = true,
    onRetry
  } = options;

  let lastError;

  // The loop will run for the initial attempt + the number of retries.
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      // Attempt to execute the function. await works for both promises and sync values.
      const result = await fn();
      return result; // If successful, return the result immediately.
    } catch (error) {
      lastError = error; // Save the error

      // If this was the last attempt, break the loop and throw the error.
      if (attempt === retries) {
        break;
      }

      // If an onRetry callback is provided, call it.
      if (onRetry) {
        onRetry(error, attempt + 1);
      }

      // Calculate delay for the next retry
      const currentDelay = backoff ? delay * (2 ** attempt) : delay;

      // Wait for the calculated delay before the next attempt.
      await sleep(currentDelay);
    }
  }

  // If the loop completes without a successful return, throw the last captured error.
  throw lastError;
}

