  if (fetchAttempts < 4) {
    throw new Error(`Network Error on attempt ${fetchAttempts}`);
  }
  return { data: "Successfully fetched data!" };
}

(async () => {
  try {
    const result = await retry(flakyFetch, {
      retries: 5,
      delay: 500,
      onRetry: (error, attempt) => {
        console.warn(`Retry attempt ${attempt} failed: ${error.message}. Retrying...`);
      }
    });
    console.log("Success:", result);
  } catch (error) {
    console.error("All retries failed:", error.message);
  }
})();


