async function retryWithBackoff(callback, maxRetries, initialDelayMs = 1000) {
  let lastError;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      return await callback();
    } catch (error) {
      lastError = error;

