### 2. Asynchronous `async/await` Version (Most Common)

In modern JavaScript, you'll often be dealing with asynchronous operations like API calls that return Promises. This version uses `async/await` to handle such cases and adds an optional delay between retries, which is a crucial best practice.

```javascript
/**
 * Retries an async callback function up to N times if it rejects or throws.
 *
 * @param {function} asyncCallback The async function (or function that returns a Promise) to execute.
 * @param {object} [options] Configuration options.
 * @param {number} [options.retries=3] The maximum number of times to retry.
 * @param {number} [options.delay=100] The delay in milliseconds between retries.
 * @returns {Promise<*>} A promise that resolves with the callback's result or rejects with the last error.
 */
async function retry(asyncCallback, options = {}) {
  const { retries = 3, delay = 100 } = options;
  let lastError;

  for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
      // Await the result of the async operation
      return await asyncCallback();
    } catch (error) {
      lastError = error;
      console.log(`Attempt ${attempt} of ${retries + 1} failed.`);

      // If this was the last attempt, break the loop to throw the error
      if (attempt > retries) {
        break;
      }

      // Wait for the specified delay before the next attempt
      if (delay > 0) {
        console.log(`Waiting ${delay}ms before retrying...`);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  console.error('All attempts failed.');
  // If the loop completes without success, reject the promise with the last error
  throw lastError;
}


