### 3. Advanced Version with Exponential Backoff

For robust applications, especially when dealing with rate-limited APIs, it's better to increase the delay after each failure. This is called "exponential backoff."

```javascript
/**
 * Retries an async function with exponential backoff.
 *
 * @param {function} asyncCallback The async function to execute.
 * @param {object} [options] Configuration options.
 * @param {number} [options.retries=3] The maximum number of retries.
 * @param {number} [options.delay=100] The initial delay in milliseconds.
 * @param {number} [options.factor=2] The factor by which the delay should increase after each retry.
 */
async function retryWithBackoff(asyncCallback, options = {}) {
  const { retries = 3, delay = 100, factor = 2 } = options;
  let currentDelay = delay;
  let lastError;

  for (let i = 0; i <= retries; i++) {
    try {
      return await asyncCallback();
    } catch (error) {
      lastError = error;
      if (i === retries) {
        // This was the last attempt
        break;
      }

      console.log(`Attempt ${i + 1} failed. Retrying in ${currentDelay}ms...`);
      await new Promise(resolve => setTimeout(resolve, currentDelay));

      // Increase the delay for the next attempt
      currentDelay *= factor;
    }
  }

  console.error('All attempts failed after exponential backoff.');
  throw lastError;
}

