        const result = await retryWithBackoff(fetchFlakyData, { retries: 3, delay: 100, factor: 3 });
        console.log('Success:', result);
    } catch (e) {
        console.error('Final failure:', e.message);
    }
}

runWithBackoff();

// Expected Output:
// Fetching data... (attempt #1)
// Attempt 1 failed. Retrying in 100ms...
// Fetching data... (attempt #2)
// Attempt 2 failed. Retrying in 300ms... (100 * 3)
// Fetching data... (attempt #3)
// Success: { id: 1, data: 'Important Info' }
