### 3. Advanced Asynchronous Version with Exponential Backoff

In real-world scenarios (like network requests), you don't want to retry immediately. Adding a delay that increases with each failure (exponential backoff) is a much better strategy.

```javascript
/**
 * A helper function to create a delay.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>}
 */
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Retries an async callback with exponential backoff.
 *
 * @param {function(): Promise} callback The async function to execute.
 * @param {number} maxRetries The maximum number of times to retry.
 * @param {object} options Optional settings.
 * @param {number} [options.delayMs=100] The base delay in milliseconds.
 * @returns {Promise<*>} A promise that resolves with the callback's result.
 */
async function retryWithBackoff(callback, maxRetries, options = {}) {
  const { delayMs = 100 } = options;
  let lastError;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      return await callback();
    } catch (error) {
      lastError = error;

      if (attempt > maxRetries) {
        // If this was the last attempt, break the loop to throw the error.
        break;
      }

      // Calculate wait time with exponential backoff and some randomness (jitter)
      const waitTime = delayMs * (2 ** (attempt - 1)) + Math.random() * delayMs;
      console.log(`Attempt ${attempt} failed. Retrying in ${Math.round(waitTime)}ms...`);
      await delay(waitTime);
    }
  }

  throw new Error(`Function failed after ${maxRetries} retries. Last error: ${lastError.message}`);
}

