 * Retries an async function if it throws an error.
 *
 * @param {Function} asyncFn The asynchronous function to execute.
 * @param {number} maxRetries The maximum number of times to retry.
 * @returns {Promise<any>} A promise that resolves with the result of the function if it succeeds.
 */
async function retry(asyncFn, maxRetries = 3) {
  let lastError;

  // The loop runs for the initial attempt + maxRetries
  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      // Attempt to execute the function and return the result if successful
      return await asyncFn();
    } catch (error) {
      lastError = error;
      console.log(`Attempt ${attempt} failed. Retrying...`);

      // If this was the last attempt, we'll exit the loop and throw
      if (attempt > maxRetries) {
        break;
      }
    }
  }

  // If all attempts fail, throw the last captured error
  console.error(`All ${maxRetries + 1} attempts failed.`);
  throw lastError;
}

// --- Example Usage ---

// A mock API call that fails 70% of the time
let callCount = 0;
function mockApiCall() {
  callCount++;
  console.log(`Making API call, attempt #${callCount}`);
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() > 0.3) { // 70% chance to fail
        reject(new Error("Network Error: Failed to fetch data."));
      } else {
        resolve({ data: "Here is your data!", attempt: callCount });
      }
    }, 500);
  });
}

// Using the retry function
async function fetchData() {
  try {
    // Retry mockApiCall up to 4 times (1 initial + 4 retries = 5 total)
    const result = await retry(mockApiCall, 4);
    console.log("Success!", result);
  } catch (error) {
    console.error("Failed to fetch data after all retries:", error.message);
  }
}

fetchData();
```

### 2. Advanced `async` Version with Delays and Exponential Backoff

In real-world applications, you don't want to retry immediately. Adding a delay, especially one that increases with each failure (exponential backoff), is crucial to avoid overwhelming a struggling service.

This version is more robust and configurable.

```javascript
/**
 * A helper function to create a delay.
 * @param {number} ms - The number of milliseconds to wait.
 */
const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Retries an async function with configurable delays and exponential backoff.
 *
 * @param {Function} asyncFn The asynchronous function to execute.
 * @param {object} [options] Configuration options.
 * @param {number} [options.retries=3] The number of times to retry.
 * @param {number} [options.delay=1000] The initial delay in ms between retries.
 * @param {number} [options.factor=2] The factor by which the delay increases after each retry.
 * @param {Function} [options.onRetry] A callback function executed on each retry attempt.
 * @returns {Promise<any>}
 */
async function retryWithBackoff(asyncFn, {
  retries = 3,
  delay = 500,
  factor = 2,
  onRetry
} = {}) {
  let lastError;

  for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
      return await asyncFn();
    } catch (error) {
      lastError = error;

      // If this was the last attempt, break out
      if (attempt > retries) {
        break;
      }

      // Call the onRetry callback if provided
      if (onRetry) {
        onRetry(error, attempt);
      }

      // Calculate delay with exponential backoff
      const waitTime = delay * (factor ** (attempt - 1));

      // Wait before the next attempt
      await wait(waitTime);
    }
  }

  throw lastError;
}


// --- Example Usage ---

let advancedCallCount = 0;
function mockFailingService() {
  advancedCallCount++;
  console.log(`Calling service, attempt #${advancedCallCount}...`);
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error("Service Unavailable")), 300);
  });
}

async function connectToService() {
  try {
    const result = await retryWithBackoff(mockFailingService, {
      retries: 4,       // Try 4 more times after the first failure
      delay: 300,       // Start with a 300ms delay
      factor: 2,        // Double the delay each time (300ms, 600ms, 1200ms, 2400ms)
      onRetry: (error, attempt) => {
        const waitTime = 300 * (2 ** (attempt - 1));
        console.warn(`Attempt ${attempt} failed: ${error.message}. Retrying in ${waitTime}ms...`);
      }
    });
    console.log("Success!", result);
  } catch (error) {
    console.error(`Service connection failed after all retries:`, error.message);
  }
}

connectToService();
```

