### 1. Asynchronous Version (using `async/await`)

This is the most common and useful version. It retries an `async` function or any function that returns a Promise.

#### The Function

```javascript
/**
 * Retries an async function (or a function that returns a Promise) up to a specified number of times.
 *
 * @param {Function} asyncFn The async function to retry.
 * @param {number} maxRetries The maximum number of times to retry.
 * @param {number} [delayMs=0] The delay in milliseconds between retries.
 * @returns {Promise<any>} A Promise that resolves with the result of the asyncFn, or rejects if all attempts fail.
 */
async function retryAsync(asyncFn, maxRetries, delayMs = 0) {
  let lastError;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    try {
      // Attempt to call the function
      const result = await asyncFn();
      // If successful, return the result immediately
      return result; 
    } catch (error) {
      lastError = error;
      console.log(`Attempt ${attempt} failed: ${error.message}`);

      // If it's not the last attempt, wait for the specified delay
      if (attempt < maxRetries + 1) {
        if (delayMs > 0) {
          await new Promise(resolve => setTimeout(resolve, delayMs));
        }
      }
    }
  }

  // If the loop completes without a successful return, all retries have failed.
  throw new Error(`Function failed after ${maxRetries + 1} attempts. Last error: ${lastError.message}`);
}
