### 3. Advanced Version with Options

For a more reusable, "production-ready" function, it's better to pass an options object. This makes the function more extensible (e.g., for adding exponential backoff).

```javascript
/**
 * A helper function to create a delay.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>}
 */
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Retries an async function with advanced options.
 * @param {function(): Promise<any>} fn The async function to execute.
 * @param {object} options Configuration options.
 * @param {number} options.maxRetries The maximum number of retries.
 * @param {number} [options.delay=1000] The base delay in ms between retries.
 * @param {boolean} [options.exponentialBackoff=false] Whether to double the delay on each retry.
 * @param {function(Error, number): void} [options.onRetry] A callback for each failed attempt.
 * @returns {Promise<any>}
 */
async function retryWithOptions(fn, options) {
  const { 
    maxRetries, 
    delay = 1000, 
    exponentialBackoff = false,
    onRetry 
  } = options;

  let lastError;

  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (onRetry) {
        onRetry(error, i + 1);
      }

      if (i < maxRetries) {
        const currentDelay = exponentialBackoff ? delay * Math.pow(2, i) : delay;
        await sleep(currentDelay);
      }
    }
  }

  throw lastError;
}

